/* ATM concept app. Works entirely in-browser; never processes real payments or contacts real owners. */
(()=>{'use strict';
const ICONS={
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',
 back:'<path d="m15 18-6-6 6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
 home:'<path d="m3 10 9-7 9 7v10h-7v-7h-4v7H3Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 bookmark:'<path d="M5 3h14v18l-7-4-7 4Z"/>',chat:'<path d="M21 11.5a8.7 8.7 0 0 1-9 8.5c-1.6 0-3.2-.4-4.5-1.2L3 20l1.2-4.4A8.8 8.8 0 1 1 21 11.5Z"/>',send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>',
 share2:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.7 10.6 6.6-4M8.7 13.4l6.6 4"/>',handshake:'<path d="m2 9 5-5 4 2 2-2 4 1 5 4-5 8-4-2-2 2-4-2Z"/><path d="m7 11 5 5m-2-8 3 1 4 3"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 star:'<path d="m12 2 3.2 6.6 7.3 1.1-5.3 5.1 1.3 7.2-6.5-3.5-6.5 3.5 1.3-7.2-5.3-5.1 7.3-1.1Z"/>',
 check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 2 8 4v6c0 5-3.8 8.5-8 10-4.2-1.5-8-5-8-10V6Z"/><path d="m9 12 2 2 4-4"/>',
 car:'<path d="m5 16-2 2v3h3v-2h12v2h3v-3l-2-2-2-7H7Z"/><path d="M5 16h14M7 9l2-4h6l2 4"/><circle cx="7" cy="17" r="1"/><circle cx="17" cy="17" r="1"/>',
 party:'<path d="M5 21 17 9 9 5Z"/><path d="M17 4h.01M21 9h.01M20 17h.01M12 2h.01M19 13h.01"/>',
 camera:'<rect x="2" y="7" width="20" height="14" rx="3"/><circle cx="12" cy="14" r="4"/><path d="m7 7 2-4h6l2 4"/>',
 wrench:'<path d="M14 6a5 5 0 0 0-6.5 6.5L3 17l4 4 4.5-4.5A5 5 0 0 0 18 10l-4 4-4-4 4-4Z"/>',
 monitor:'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 22h8M12 18v4"/>',
 tractor:'<circle cx="7" cy="17" r="4"/><circle cx="19" cy="18" r="2"/><path d="M3 17V9h10l3 8M13 9V5h5M2 9h4"/>',
 sparkles:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3Z"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M9 7V4h6v3M3 13h18"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 credit:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M15 10h7v6h-7a3 3 0 0 1 0-6Z"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.3-2l2-2-2-3-2.7 1a8 8 0 0 0-3-1l-.8-3H9.8L9 5a8 8 0 0 0-3 1L3.3 5l-2 3 2 2a7 7 0 0 0 0 4l-2 2 2 3L6 18a8 8 0 0 0 3 1l.8 3h2.4l.8-3a8 8 0 0 0 3-1l2.7 1 2-3-2-2a7 7 0 0 0 .3-2Z"/>',
 help:'<circle cx="12" cy="12" r="10"/><path d="M9.5 9a2.8 2.8 0 1 1 4.1 2.4c-1 .6-1.6 1.2-1.6 2.6M12 17h.01"/>',
 edit:'<path d="M12 20h9M16 4l4 4L9 19l-5 1 1-5L16 4Z"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',
 logout:'<path d="M10 3H5v18h5M14 7l5 5-5 5M19 12H8"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 10a8 8 0 0 1 13-4l2 1M4 17l2 1a8 8 0 0 0 13-4"/>',
 phone:'<path d="M7 2h10v20H7Z"/><path d="M11 18h2"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',
 link:'<path d="M10 13a5 5 0 0 0 7 .2l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.2l-3 3a5 5 0 0 0 7 7l2-2"/>',
 package:'<path d="m12 2 9 5v10l-9 5-9-5V7Z"/><path d="m3 7 9 5 9-5M12 12v10"/>',
 list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01"/>',
 alert:'<path d="m12 2 10 18H2Z"/><path d="M12 9v4M12 17h.01"/>',
 map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Z"/><path d="M9 3v15M15 6v15"/>'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.grid}</svg>`}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'K'+Math.round(Number(n)||0).toLocaleString('en-US');
const STORAGE_KEY='atm-marketplace-demo-v3';
const defaultState=()=>({name:'Mwamba Phiri',city:'Lusaka',email:'demo@atm.example',favorites:[],likes:[],offers:[],bookings:[],myListings:[],notifications:ATM_START_NOTICES,conversations:ATM_START_CHATS,comments:{},paymentMethods:[],payout:{},preferences:{updates:true,bookingAlerts:true},reports:[]});
let state;try{state={...defaultState(),...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch(_){state=defaultState()}
if(!Array.isArray(state.offers))state.offers=[];
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(err){console.warn('Browser storage is full; data may not persist.',err);toast('Browser storage is full; recent changes may not persist')}}
const ui={category:'All',city:'All cities',query:'',sort:'Trending',sheet:null,photoIdx:0,booking:null,helpOpen:-1,postPreview:'',returnTo:'home',activityTab:'notifications'};
let toastTimer;
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
const listings=()=>[...state.myListings.filter(l=>!l.deleted),...ATM_LISTINGS];
const getListing=id=>listings().find(l=>String(l.id)===String(id));
const myListing=id=>state.myListings.find(l=>String(l.id)===String(id));
const saved=id=>state.favorites.includes(String(id));
const liked=id=>state.likes.includes(String(id));
const avatar=(name,size='')=>`<div class="avatar ${name.length%3===0?'purple':name.length%2===0?'orange':''}" ${size?`style="${size}"`:''}>${esc(name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase())}</div>`;
const image=(l,cls='',other='')=>`<img class="${cls}" src="${esc(l.image||photo(l.img)||photo('tent'))}" alt="${esc(l.title)}" loading="lazy" onerror="this.onerror=null;this.style.opacity='.05';this.parentElement.classList.add('image-fallback')" ${other}>`;
const verify=l=>l.verified?`<span class="verified">${icon('shield')} Verified demo seller</span>`:'';
const pagePath=()=>decodeURIComponent((location.hash||'#/home').replace(/^#\/?/,'')).split('/').filter(Boolean);
function go(route,id){const target=`#/${route}${id!==undefined&&id!==null?'/'+encodeURIComponent(id):''}`;ui.sheet=null;ui.photoIdx=0;if(location.hash===target){render();scrollTo(0,0)}else{location.hash=target}}
function activeNav(page){if(['home'].includes(page))return 'home';if(['explore','trending','listing','comments','book','checkout','success','offers'].includes(page))return 'explore';if(['post','edit'].includes(page))return 'post';return 'account'}
function navBar(page){const active=activeNav(page);const tabs=[['home','home','Home'],['explore','grid','Explore'],['post','plus','Post'],['account','user','Account']];return `<nav class="fnav" aria-label="Main navigation">${tabs.map(([p,ic,text])=>`<button aria-label="${text}" aria-current="${p===active?'page':'false'}" class="${p===active?'active':''}" data-action="go" data-route="${p}">${icon(ic,ic==='plus'?'add-icon':'')}<span>${text}</span></button>`).join('')}</nav>`}
function header(page){const back=!['home','explore','post','account'].includes(page);const unread=state.notifications.filter(n=>!n.read).length;return `<header class="topbar"><div>${back?`<button class="back-btn" data-action="back" aria-label="Back">${icon('back')}</button>`:''}</div><div class="brand" aria-label="ATM">ATM</div><button class="bell-btn" aria-label="Notifications${unread?' '+unread+' unread':''}" data-action="go" data-route="notifications">${icon('bell')}${unread?`<span class="notif-dot">${unread>9?'9+':unread}</span>`:''}</button></header>`}
function sectionTitle(title,route,txt='See All'){return `<div class="section-head"><h2>${title}</h2><button class="see-all" data-action="go" data-route="${route}">${txt} ${icon('chevron')}</button></div>`}
function categoryRow(){return `<div class="category-rail" aria-label="Popular rental categories">${ATM_CATEGORIES.slice(1).map(c=>`<button class="category-item" data-action="category" data-value="${esc(c.name)}"><span class="category-ball">${icon(c.icon)}</span><span>${esc(c.name)}</span></button>`).join('')}</div>`}
function trendCard(l){return `<div class="trend-card" role="group" aria-label="${esc(l.title)}"> <button data-action="listing" data-id="${l.id}" style="position:absolute;inset:0;width:100%;padding:0" aria-label="View ${esc(l.title)}">${image(l,'card-media')}</button><button data-action="save" data-id="${l.id}" class="trend-save ${saved(l.id)?'is-saved':''}" aria-label="${saved(l.id)?'Remove saved':'Save'} ${esc(l.title)}">${icon('heart')}</button><div class="trend-text"><strong>${esc(l.title)}</strong><span>From ${money(l.price)}/day</span></div></div>`}
function feedCard(l){return `<article class="feed-card" role="link" tabindex="0" data-action="listing" data-id="${l.id}" aria-label="View ${esc(l.title)} details"><div class="feed-author"><span class="avatar-wrap">${avatar(l.owner)}<span class="seller-online" aria-label="Sample seller activity"></span></span><div class="author-meta"><strong>${esc(l.owner)}</strong><span>${esc(l.city)}, Zambia · ${l.created}h ago</span></div></div><div class="feed-photo-btn">${image(l,'feed-photo')}<span class="photo-counter">1/3</span></div><div class="feed-actions"><button class="icon-btn" data-action="share" data-id="${l.id}" aria-label="Share ${esc(l.title)}">${icon('share2')}</button><span class="spacer"></span><button class="icon-btn ${saved(l.id)?'is-saved':''}" data-action="save" data-id="${l.id}" aria-label="${saved(l.id)?'Remove saved':'Save'} ${esc(l.title)}">${icon('bookmark')}</button></div><div class="feed-title">${esc(l.title)}</div><div class="feed-price">${money(l.price)}<span style="font-size:13px;color:#777;font-weight:500"> / day</span></div><div class="feed-description">${esc(l.description)}</div><div class="feed-bottom"><div class="feed-rating" aria-label="${l.reviews?`${l.rating} out of 5, ${l.reviews} illustrative reviews`:'No reviews yet'}">${l.reviews?`<span class="review-stars" aria-hidden="true">${'★'.repeat(Math.round(l.rating))}${'☆'.repeat(5-Math.round(l.rating))}</span><strong>${Number(l.rating).toFixed(1)}</strong><span>(${l.reviews} sample reviews)</span>`:'<span class="no-reviews">New · No reviews yet</span>'}</div><span class="card-tap-hint">View details ${icon('chevron')}</span></div></article>`}
function home(){return `<section class="screen reveal"><div class="home-top"><div class="welcome"><h1 class="desktop-intro">Anything you need.<br>Available to hire.</h1><p>Find it. Hire it. Enjoy it. Across Zambia.</p></div><button class="searchbar home-search" data-action="search" aria-label="Search rentals">${icon('search')}<span>What do you want to hire?</span></button></div>${sectionTitle('Trending','trending','Explore')} ${categoryRow()}<section class="trend-section">${sectionTitle('Trending for Hire in Zambia','trending')}<div class="trending-rail">${ATM_LISTINGS.filter(x=>x.featured).map(trendCard).join('')}</div></section><section>${sectionTitle('Latest in your community','explore','Browse all')}<div class="feed">${ATM_LISTINGS.filter(x=>!x.featured).map(feedCard).join('')}</div></section><div class="banner"><div><h3>Have something to hire out?</h3><p>Turn an item you own into an opportunity. Create your first listing.</p></div><button class="btn" data-action="go" data-route="post">List now ${icon('chevron')}</button></div><p class="demo-label">ATM concept preview · Sample listings and fictional owners · All transactions simulated</p></section>`}
function tile(l){return `<div class="listing-tile"><div class="tile-media"><button data-action="listing" data-id="${l.id}" style="display:block;width:100%;padding:0;text-align:left">${image(l,'tile-image')}</button><button class="tile-save ${saved(l.id)?'is-saved':''}" data-action="save" data-id="${l.id}" aria-label="Save ${esc(l.title)}">${icon('heart')}</button></div><button data-action="listing" data-id="${l.id}" style="display:block;text-align:left;padding:0;width:100%"><div class="tile-name">${esc(l.title)}</div><div class="tile-city">${icon('pin')} ${esc(l.city)} · ★ ${l.rating}</div><div class="tile-price">${money(l.price)} <span>/ day</span></div></button></div>`}
const cities=['All cities','Lusaka','Ndola','Kitwe','Livingstone','Kabwe','Chingola','Solwezi','Chipata','Mazabuka','Mansa','Chilanga','Siavonga'];
function explore(page){const isTrending=page==='trending';let results=listings().filter(l=>(!isTrending||l.featured)&&(ui.category==='All'||l.category===ui.category)&&(ui.city==='All cities'||l.city===ui.city)&&(!ui.query||(`${l.title} ${l.owner} ${l.city} ${l.description} ${l.category}`).toLowerCase().includes(ui.query.toLowerCase())));if(ui.sort==='Price: low')results.sort((a,b)=>a.price-b.price);else if(ui.sort==='Price: high')results.sort((a,b)=>b.price-a.price);else if(ui.sort==='Top rated')results.sort((a,b)=>b.rating-a.rating);else if(ui.sort==='Newest')results.sort((a,b)=>b.id-a.id);return `<div class="screen reveal"><div class="page-top"><h1 class="page-title">${isTrending?'Trending for Hire':'Explore rentals'}</h1><p>${isTrending?'The top 20 trending items to hire across Zambia.':'What will you hire today? Browse everything on ATM.'}</p></div><div class="filter-controls"><div class="search-col"><label class="form-label" for="search-listings" style="margin:0 0 7px">Search</label><input id="search-listings" class="form-input" type="search" placeholder="Try: Prado, tent, camera..." value="${esc(ui.query)}" data-input="search"></div><div><label for="city-filter" class="form-label" style="margin:0 0 7px">Location</label><select id="city-filter" class="form-select" data-change="city">${cities.map(c=>`<option ${ui.city===c?'selected':''}>${c}</option>`).join('')}</select></div><div><label for="sort-filter" class="form-label" style="margin:0 0 7px">Sort by</label><select id="sort-filter" class="form-select" data-change="sort">${['Trending','Newest','Price: low','Price: high','Top rated'].map(s=>`<option ${ui.sort===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="chip-strip">${ATM_CATEGORIES.map(c=>`<button class="chip ${ui.category===c.name?'active':''}" data-action="category" data-value="${c.name}">${icon(c.icon)}${c.name}</button>`).join('')}</div><div class="page-actions"><div class="results-line">${results.length} listing${results.length===1?'':'s'} found</div><button class="link-btn" data-action="resetfilters">Reset filters</button></div>${results.length?`<div class="listing-grid">${results.map(tile).join('')}</div>`:empty('search','No rentals found','Try a different category, search phrase or location.','Reset filters','resetfilters')}</div>`}
function gallery(l){let photos=[l.image,...ATM_LISTINGS.filter(x=>x.category===l.category&&x.id!==l.id).slice(0,2).map(x=>x.image)];return photos}
function detail(l){if(!l)return notFound();const pics=gallery(l);return `<div class="screen reveal"><div class="detail-layout"><main><div class="detail-hero">${image({...l,image:pics[ui.photoIdx]||pics[0]},'hero-image')}<button class="detail-heart ${saved(l.id)?'is-saved':''}" data-action="save" data-id="${l.id}" aria-label="Save">${icon('heart')}</button></div><div class="thumbs">${pics.map((p,i)=>`<button data-action="gallery" data-index="${i}" aria-label="Show image ${i+1}"><img src="${esc(p)}" alt="${esc(l.title)} image ${i+1}" class="${ui.photoIdx===i?'selected':''}" onerror="this.style.opacity='.15'"></button>`).join('')}</div><div class="detail-header"><div><h1>${esc(l.title)}</h1><div class="info-row">${icon('pin')}${esc(l.city)}, Zambia</div><div class="info-row"><span class="stars">★</span> ${l.rating} (${l.reviews} demo reviews) · ${esc(l.category)}</div></div><div class="detail-price">${money(l.price)}<small> / day</small></div></div><div class="divider"></div><div class="detail-section"><h3>About this hire</h3><p>${esc(l.description)}</p></div><div class="owner-card">${avatar(l.owner)}<div class="owner-copy"><strong>${esc(l.owner)}</strong><span>Listing host in ${esc(l.city)}</span><div style="margin-top:5px">${verify(l)}</div></div><button class="btn outline small" data-action="chat" data-id="${l.id}">${icon('chat')} Chat</button></div><div class="detail-section"><h3>Rental guidelines</h3><div class="rules">${['Agree on pickup, return and inspection details with the host.','Check the item condition before handover.','Any deposit or payment in this preview is simulated.','ATM demo listings are fictional and cannot be booked in real life.'].map(t=>`<div class="rule">${icon('check')}<span>${t}</span></div>`).join('')}</div></div><div class="detail-section"><h3>Questions?</h3><p>Message this demo host or view the sample comments.</p><div class="page-toolbar"><button class="btn outline" data-action="chat" data-id="${l.id}">${icon('chat')} Message host</button><button class="btn outline" data-action="comments" data-id="${l.id}">${icon('chat')} Comments</button><button class="btn outline" data-action="share" data-id="${l.id}">${icon('share2')} Share</button></div></div></main><aside class="detail-sidebar"><span class="eyebrow">READY WHEN YOU ARE</span><h3 style="margin-top:8px">Hire this item</h3><p class="subtle">${money(l.price)} per day in ${esc(l.city)}</p><form data-form="quickbook" data-id="${l.id}"><label class="form-label" for="detail-start">Start date</label><input class="form-input" id="detail-start" name="start" type="date" min="${dateISO(new Date())}" required><label class="form-label" for="detail-end">Return date</label><input class="form-input" id="detail-end" name="end" type="date" min="${dateISO(new Date())}" required><div class="price-summary"><div class="price-row"><span>Day rate</span><strong>${money(l.price)}</strong></div><div class="price-row"><span>Illustrative refundable deposit</span><strong>${money(l.deposit)}</strong></div><div class="price-row total"><span>Booking</span><strong>Calculate at checkout</strong></div></div><button class="btn primary wide" type="submit">Check dates & continue ${icon('chevron')}</button></form><button class="btn offer-primary wide" data-action="offer" data-id="${l.id}">${icon('handshake')} Make an offer</button><button class="btn outline wide" style="margin-top:10px" data-action="chat" data-id="${l.id}">${icon('chat')} Chat with host</button><div class="note">Concept only. No real availability check, owner contact or financial transaction takes place.</div></aside></div></div>`}
const dateISO=d=>{const yr=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${yr}-${m}-${day}`};
const daysBetween=(a,b)=>Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)+1;
function book(l){if(!l)return notFound();return `<div class="screen reveal" style="max-width:730px;margin:auto"><div class="page-top"><h1>Choose your hire dates</h1><p>Book a demo request for ${esc(l.title)}.</p></div><div class="booking-card"><div class="booking-card-top">${image(l,'')}<div><strong>${esc(l.title)}</strong><p>${esc(l.city)} · ${esc(l.owner)}</p><strong>${money(ui.booking?.agreedRate??l.price)}/day${ui.booking?.agreedRate?' · Accepted offer':''}</strong></div></div></div><form data-form="book" data-id="${l.id}"><div class="form-row"><div><label class="form-label" for="book-start">Pick-up date <em>*</em></label><input id="book-start" type="date" class="form-input" name="start" value="${ui.booking?.start||''}" min="${dateISO(new Date())}" required></div><div><label class="form-label" for="book-end">Return date <em>*</em></label><input id="book-end" type="date" class="form-input" name="end" value="${ui.booking?.end||''}" min="${dateISO(new Date())}" required></div></div><label class="form-label" for="book-fulfillment">Collection preference</label><select id="book-fulfillment" class="form-select" name="fulfillment"><option value="Pick up from host">Pick up from host</option><option value="Ask for delivery">Ask for delivery (subject to agreement)</option></select><label class="form-label" for="book-note">Note for the host (optional)</label><textarea id="book-note" name="note" class="form-textarea" placeholder="E.g. I need the tent for a wedding in Kabulonga."></textarea><div class="notice-banner">${icon('info')} Your dates are part of a local demo request. They are not checked against a real provider’s calendar.</div><button class="btn primary wide" type="submit">Continue to demo checkout ${icon('chevron')}</button></form></div>`}
function checkout(l){if(!l||!ui.booking||String(ui.booking.id)!==String(l.id))return `<div class="screen">${empty('calendar','No dates selected','Choose your hire dates to continue.','Choose dates','book',l?.id)}</div>`;const d=daysBetween(ui.booking.start,ui.booking.end),rate=ui.booking.agreedRate??l.price,rent=d*rate,deposit=l.deposit,total=rent+deposit;return `<div class="screen reveal" style="max-width:700px;margin:auto"><div class="page-top"><h1>Review your booking</h1><p>Confirm the details for your simulated rental.</p></div><div class="booking-card"><div class="booking-card-top">${image(l)}<div><strong>${esc(l.title)}</strong><p>${esc(l.city)} · ${ui.booking.start} to ${ui.booking.end}</p><p>${d} day${d>1?'s':''} · ${esc(ui.booking.fulfillment)}</p></div></div></div><div class="price-summary"><div class="price-row"><span>${money(rate)} × ${d} day${d>1?'s':''}</span><strong>${money(rent)}</strong></div><div class="price-row"><span>Illustrative refundable deposit</span><strong>${money(deposit)}</strong></div><div class="price-row total"><span>Illustrative total</span><strong>${money(total)}</strong></div></div><h3 style="margin:22px 0 12px">Choose a demo payment method</h3><form data-form="checkout" data-id="${l.id}"><label class="payment-option selected"><input type="radio" name="method" value="Pay on handover (demo)" checked><div class="payment-copy"><strong>Pay on handover</strong><small>No payment collected in the demo</small></div>${icon('wallet')}</label><label class="payment-option"><input type="radio" name="method" value="Mobile Money (demo)"><div class="payment-copy"><strong>Mobile Money — demo</strong><small>See a simulated MTN / Airtel / Zamtel confirmation</small></div>${icon('phone')}</label><label class="payment-option"><input type="radio" name="method" value="Bank transfer (demo)"><div class="payment-copy"><strong>Bank transfer — demo</strong><small>Simulated confirmation only</small></div>${icon('credit')}</label><div class="note">No funds move. The payment method is recorded only as part of the prototype, and no real provider receives your request.</div><button class="btn primary wide" type="submit">Place demo booking ${icon('check')}</button></form></div>`}
function bookingSuccess(id){let b=state.bookings.find(x=>String(x.id)===String(id));if(!b)return notFound();const l=getListing(b.listingId);return `<div class="screen success-panel reveal"><div class="success-icon">${icon('check')}</div><h1>Demo booking created!</h1><p>Your request has been saved in this browser. This does not reserve a real item or charge you money.</p><div class="price-summary"><div class="price-row"><span>Reference</span><strong>${esc(b.ref)}</strong></div><div class="price-row"><span>Rental</span><strong>${esc(l?.title||'Listing')}</strong></div><div class="price-row"><span>Dates</span><strong>${b.start} to ${b.end}</strong></div><div class="price-row"><span>Method</span><strong>${esc(b.method)}</strong></div><div class="price-row total"><span>Illustrative total</span><strong>${money(b.total)}</strong></div></div><div class="stack"><button class="btn primary wide" data-action="go" data-route="rentals">View my rentals</button><button class="btn outline wide" data-action="chat" data-id="${l?.id||1}">${icon('chat')} Message demo host</button><button class="btn soft wide" data-action="go" data-route="home">Back to home</button></div></div>`}
function notifications(){return `<section class="screen reveal"><div class="page-top"><h1>Notifications</h1><p>Updates about your bookings, listings and conversations.</p></div><div class="page-actions"><span class="subtle">${state.notifications.filter(n=>!n.read).length} unread</span><button class="link-btn" data-action="markall">Mark all as read</button></div>${state.notifications.length?state.notifications.map(n=>`<button class="list-row ${n.read?'':'unread'}" data-action="notification" data-id="${n.id}"><span class="row-icon">${icon(n.kind==='booking'?'calendar':n.kind==='chat'?'chat':n.kind==='post'?'check':n.kind==='tip'?'shield':'bell')}</span><span class="row-copy"><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p></span><span class="row-end">${esc(n.age||'Now')}</span>${icon('chevron','row-chevron')}</button>`).join(''):empty('bell','All caught up','Notifications about your demo activity will appear here.','Explore rentals','explore')}</section>`}
function account(){return `<div class="screen reveal"><div class="page-top"><div class="account-hero">${avatar(state.name)}<div><h1>${esc(state.name)}</h1><p>${esc(state.city)}, Zambia</p><button class="link-btn" style="margin-top:6px" data-action="go" data-route="profile">Edit profile</button></div></div></div><div class="stat-grid"><div class="stat"><strong>${state.myListings.filter(x=>!x.deleted).length}</strong><span>Listings</span></div><div class="stat"><strong>${state.bookings.length}</strong><span>Bookings</span></div><div class="stat"><strong>${state.favorites.length}</strong><span>Saved</span></div></div><p class="group-label">My marketplace</p>${[['list','My listings','Manage your items for hire','mylistings'],['calendar','My rentals','Track bookings and requests','rentals'],['handshake','My offers','Review offers, replies and agreed rates','offers'],['heart','Saved items','Your favourite rentals','saved'],['chat','Messages','Talk to demo listing owners','messages']].map(accountRow).join('')}<p class="group-label">Payments & account</p>${[['credit','Payment methods','Manage saved demo methods','paymentmethods'],['wallet','Payout settings','Your future owner payouts','payouts'],['bell','Notifications','Updates and reminders','notifications'],['help','Help & safety','How hiring works','help'],['settings','Settings','Preferences and reset','settings']].map(accountRow).join('')}<p class="demo-label">ATM · Client concept, not a live marketplace</p></div>`}
function accountRow([ic,title,desc,route]){return `<button class="list-row" data-action="go" data-route="${route}"><span class="row-icon">${icon(ic)}</span><span class="row-copy"><strong>${title}</strong><p>${desc}</p></span>${icon('chevron','row-chevron')}</button>`}
function empty(ic,title,body,button,route,id){return `<div class="empty"><div class="empty-symbol">${icon(ic)}</div><h3>${title}</h3><p>${body}</p><button class="btn primary" data-action="${route==='resetfilters'?'resetfilters':'go'}" ${route==='resetfilters'?'':`data-route="${route}"`}${id?` data-id="${id}"`:''}>${button}</button></div>`}
function savedPage(){const items=listings().filter(l=>saved(l.id));return `<div class="screen reveal"><div class="page-top"><h1>Saved items</h1><p>Rentals you might want to return to.</p></div>${items.length?`<div class="listing-grid">${items.map(tile).join('')}</div>`:empty('heart','No saved items yet','Tap the bookmark on a listing to find it here later.','Explore rentals','explore')}</div>`}
function myListings(){const items=state.myListings.filter(x=>!x.deleted);return `<div class="screen reveal"><div class="page-top"><h1>My listings</h1><p>Manage what you have available to hire.</p></div><div class="page-actions"><span class="subtle">${items.length} active demo listing${items.length===1?'':'s'}</span><button class="btn primary" data-action="go" data-route="post">${icon('plus')} New listing</button></div>${items.length?items.map(l=>`<div class="my-listing-row">${image(l)}<div><strong>${esc(l.title)}</strong><p>${money(l.price)} / day · ${esc(l.city)} · Live in demo</p><button class="btn small outline" data-action="editlisting" data-id="${l.id}">${icon('edit')} Edit</button><button class="btn small outline" data-action="deletelisting" data-id="${l.id}">${icon('trash')} Delete</button><button class="btn small primary" data-action="listing" data-id="${l.id}">View</button></div></div>`).join(''):empty('package','You have not listed anything','Publish your first item to see it on ATM Explore.','Create a listing','post')}</div>`}
function rentals(){return `<div class="screen reveal"><div class="page-top"><h1>My rentals</h1><p>Track your demo hire requests and confirmations.</p></div>${state.bookings.length?state.bookings.slice().reverse().map(b=>{const l=getListing(b.listingId);return `<div class="booking-card"><div class="booking-card-top">${l?image(l):''}<div><strong>${esc(l?.title||'Deleted listing')}</strong><p>${b.start} – ${b.end} · ${esc(l?.city||'Zambia')}</p><p>${esc(b.ref)}</p><span class="badge ${b.status==='Cancelled'?'cancelled':b.status==='Confirmed (demo)'?'confirmed':'pending'}">${esc(b.status)}</span></div></div><div class="price-row"><span>Demo total</span><strong>${money(b.total)}</strong></div><div class="booking-card-actions">${b.status!=='Cancelled'?`<button class="btn small outline" data-action="cancelbooking" data-id="${b.id}">Cancel request</button>`:''}${l?`<button class="btn small primary" data-action="chat" data-id="${l.id}">Message host</button>`:''}<button class="btn small outline" data-action="receipt" data-id="${b.id}">View details</button></div></div>`}).join(''):empty('calendar','No bookings yet','Explore items for hire and place your first demo rental request.','Explore rentals','explore')}</div>`}
function conversations(){return `<div class="screen reveal"><div class="page-top"><h1>Messages</h1><p>All your conversations with demo hosts.</p></div>${state.conversations.map(c=>{const l=getListing(c.listingId);const last=c.messages.at(-1);return `<button class="inbox-row" data-action="go" data-route="chat" data-id="${c.id}">${avatar(c.person)}<span class="row-copy"><strong>${esc(c.person)}</strong><p>${esc(last?.text||'Start a conversation')}</p><small>${esc(l?.title||'Support')}</small></span>${icon('chevron')}</button>`}).join('')||empty('chat','No conversations','Open a listing and tap Message host to start chatting.','Explore','explore')}<div class="notice-banner">${icon('info')} Messages are simulated and stored in your browser. No real seller receives them.</div></div>`}
function chatPage(id){const c=state.conversations.find(c=>String(c.id)===String(id));if(!c)return notFound();const l=getListing(c.listingId);return `<div class="screen reveal chat-panel"><div class="owner-card" style="margin:0">${avatar(c.person)}<div class="owner-copy"><strong>${esc(c.person)}</strong><span>${esc(l?.title||'ATM support')} · Demo conversation</span></div>${l?`<button class="btn small outline" data-action="listing" data-id="${l.id}">Listing</button>`:''}</div><div class="chat-messages" id="messages-list">${c.messages.map(m=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}<small>${esc(m.time)}</small></div>`).join('')}</div><form class="chat-compose" data-form="chat" data-id="${c.id}"><input class="form-input" aria-label="Write a message" name="message" placeholder="Type a message..." maxlength="500" required><button type="submit" aria-label="Send">${icon('send')}</button></form></div>`}
function postPage(id){const l=id?myListing(id):null;if(id&&!l)return notFound();const preview=ui.postPreview||l?.image||'';return `<div class="screen reveal post-form"><div class="page-top"><h1>${l?'Edit your listing':'Add a new listing'}</h1><p>Give your item a great description and set the daily hire rate.</p></div><div class="notice-banner">${icon('info')} This is a working prototype: listings you publish appear in Explore immediately, but are stored only in this browser.</div><form data-form="post" data-id="${l?.id||''}"><label class="form-label">Listing photo</label><div class="post-preview" id="post-photo">${preview?`<img src="${esc(preview)}" alt="Photo preview" onerror="this.style.display='none'">`:`<span>${icon('image')} Your photo appears here</span>`}</div><label class="form-label" for="post-image">Image URL (optional)</label><input class="form-input" type="url" id="post-image" name="image" value="${esc(l?.image?.startsWith('data:')?'':l?.image||'')}" placeholder="https://example.com/photo.jpg"><div class="form-hint">Paste a photo URL, upload your own image below, or use a sample category photo.</div><label class="form-label" for="post-upload">Upload image from your device (up to 1.5 MB)</label><input id="post-upload" class="form-input" type="file" accept="image/jpeg,image/png,image/webp" data-upload="post-photo"><label class="form-label" for="post-title">Title <em>*</em></label><input id="post-title" name="title" class="form-input" placeholder="E.g. Toyota Hilux Double Cab for Hire" value="${esc(l?.title||'')}" minlength="5" maxlength="95" required><div class="form-row"><div><label class="form-label" for="post-category">Category <em>*</em></label><select id="post-category" name="category" class="form-select" required>${ATM_CATEGORIES.slice(1).map(c=>`<option ${l?.category===c.name?'selected':''}>${c.name}</option>`).join('')}</select></div><div><label class="form-label" for="post-city">Location <em>*</em></label><select id="post-city" class="form-select" name="city" required>${cities.slice(1).map(c=>`<option ${l?.city===c||(!l&&c===state.city)?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="form-row"><div><label class="form-label" for="post-price">Daily price (K) <em>*</em></label><input id="post-price" class="form-input" type="number" inputmode="decimal" min="1" max="1000000" step="1" name="price" placeholder="E.g. 500" value="${l?.price||''}" required></div><div><label class="form-label" for="post-deposit">Deposit (K)</label><input id="post-deposit" class="form-input" type="number" min="0" max="1000000" step="1" name="deposit" placeholder="E.g. 100" value="${l?.deposit??''}"></div></div><label class="form-label" for="post-description">Description <em>*</em></label><textarea id="post-description" class="form-textarea" name="description" placeholder="What makes this item great? Include its condition, what is included, delivery and hire rules." minlength="20" maxlength="1500" required>${esc(l?.description||'')}</textarea><div class="form-footer"><button class="btn primary wide" type="submit">${l?'Save changes':'Publish demo listing'} ${icon('check')}</button></div></form></div>`}
function commentsPage(l){if(!l)return notFound();const defaults=[['Chilufya M.','Looks great! Is it still available?'],['Tandiwe K.','Thanks for sharing the details.']];const own=state.comments[l.id]||[];return `<div class="screen reveal" style="max-width:720px;margin:auto"><div class="page-top"><h1>Comments</h1><p>${esc(l.title)}</p></div><div class="booking-card"><div class="booking-card-top">${image(l)}<div><strong>${esc(l.title)}</strong><p>${esc(l.city)} · ${money(l.price)} / day</p><button class="link-btn" data-action="listing" data-id="${l.id}">View listing</button></div></div></div>${[...defaults.map(([name,text])=>({name,text})),...own].map(x=>`<div class="comment-card">${avatar(x.name)}<div><strong>${esc(x.name)}</strong><p>${esc(x.text)}</p><small class="muted">Demo conversation</small></div></div>`).join('')}<form data-form="comment" data-id="${l.id}" class="comment-composer"><input class="form-input" name="comment" maxlength="280" placeholder="Write a comment..." required><button class="btn primary" type="submit">Post</button></form></div>`}
function profilePage(){return `<div class="screen reveal post-form"><div class="page-top"><h1>Edit profile</h1><p>Personalise your local ATM demo account.</p></div><form data-form="profile"><label class="form-label" for="profile-name">Full name</label><input class="form-input" id="profile-name" name="name" value="${esc(state.name)}" required minlength="2"><label class="form-label" for="profile-email">Email address</label><input class="form-input" id="profile-email" name="email" value="${esc(state.email)}" type="email" required><label class="form-label" for="profile-city">City</label><select id="profile-city" name="city" class="form-select">${cities.slice(1).map(c=>`<option ${state.city===c?'selected':''}>${c}</option>`).join('')}</select><div class="form-footer"><button class="btn primary wide" type="submit">Save profile</button></div></form></div>`}
function paymentMethods(){return `<div class="screen reveal post-form"><div class="page-top"><h1>Payment methods</h1><p>Optional payment preferences for the demo account.</p></div>${state.paymentMethods.map((p,i)=>`<div class="list-row"><span class="row-icon">${icon('phone')}</span><span class="row-copy"><strong>${esc(p.provider)}</strong><p>${esc(p.masked)}</p></span><button class="btn small outline" data-action="removemethod" data-id="${i}">Remove</button></div>`).join('')}${!state.paymentMethods.length?`<div class="alert">There are no saved demo methods. ATM never asks for a PIN or real card credentials.</div>`:''}<h3 style="margin:25px 0 8px">Add demo Mobile Money method</h3><form data-form="method"><label class="form-label" for="method-provider">Network</label><select class="form-select" name="provider" id="method-provider"><option>MTN Mobile Money</option><option>Airtel Money</option><option>Zamtel Kwacha</option></select><label class="form-label" for="method-number">Mobile number (demo only)</label><input class="form-input" id="method-number" name="number" placeholder="097XXXXXXX" inputmode="tel" minlength="9" maxlength="13" required><p class="form-hint">Only the final 3 digits are kept in local browser storage. No real verification or collection occurs.</p><div class="form-footer"><button class="btn primary wide" type="submit">Save demo method</button></div></form></div>`}
function payoutPage(){return `<div class="screen reveal post-form"><div class="page-top"><h1>Payout settings</h1><p>Where rental earnings could be sent when ATM becomes a live platform.</p></div><div class="stat-grid"><div class="stat"><strong>K0</strong><span>Available</span></div><div class="stat"><strong>K0</strong><span>Pending</span></div><div class="stat"><strong>K0</strong><span>Paid out</span></div></div><div class="notice-banner">${icon('info')} No live financial accounts are connected and ATM does not process money. Your chosen demo preference is stored locally.</div><form data-form="payout"><label class="form-label" for="payout-provider">Preferred demo payout channel</label><select name="provider" id="payout-provider" class="form-select"><option ${state.payout.provider==='MTN Mobile Money'?'selected':''}>MTN Mobile Money</option><option ${state.payout.provider==='Airtel Money'?'selected':''}>Airtel Money</option><option ${state.payout.provider==='Zamtel Kwacha'?'selected':''}>Zamtel Kwacha</option><option ${state.payout.provider==='Bank transfer'?'selected':''}>Bank transfer</option></select><label class="form-label" for="payout-label">Payout nickname (not an account number)</label><input class="form-input" name="label" id="payout-label" placeholder="E.g. My business wallet" value="${esc(state.payout.label||'')}" required><div class="form-footer"><button class="btn primary wide" type="submit">Save payout preference</button></div></form></div>`}
const FAQS=[['How does ATM work?','Browse items, choose dates, message the host, and arrange a rental. This prototype demonstrates the flow; real listings and booking services are not connected.'],['Can I rent anything?','The intended marketplace supports vehicles, equipment, event supplies, tools, short stays, fashion and other legal items. Regulated or unsafe items would require marketplace restrictions before a live launch.'],['How are payments handled?','In this concept all payments are simulated. In a production app, a licensed payment partner, dispute handling, deposits and refunds would be designed and verified before launch.'],['How do I stay safe?','Verify the owner, inspect the item, agree on written rental conditions and handover details, and avoid paying off-platform to unknown parties.'],['How do I add an item?','Open Post in the floating bar, add photos and details, set your rate and publish. Your demo listing will immediately appear in Explore.'],['Are my details shared?','No. Your prototype changes are stored in your current browser with localStorage, not a cloud database. Resetting the demo clears that data.']];
function helpPage(){return `<div class="screen reveal post-form"><div class="page-top"><h1>Help & safety</h1><p>Answers to common questions about hiring with ATM.</p></div>${FAQS.map(([q,a],i)=>`<div style="border-bottom:1px solid #eee;padding:16px 2px"><button style="display:flex;align-items:center;justify-content:space-between;width:100%;text-align:left;font-weight:850;gap:14px" data-action="faq" data-id="${i}">${q}${icon(ui.helpOpen===i?'down':'chevron')}</button>${ui.helpOpen===i?`<p style="color:#666;font-size:14px;line-height:1.7;margin-top:13px">${a}</p>`:''}</div>`).join('')}<div class="banner"><div><h3>Need further help?</h3><p>Send a message through our working demo support inbox.</p></div><button class="btn" data-action="support">Contact</button></div><button class="btn outline wide" data-action="report">${icon('alert')} Report an issue</button></div>`}
function settingsPage(){return `<div class="screen reveal post-form"><div class="page-top"><h1>Settings</h1><p>Control your ATM demo experience.</p></div><div class="toggle-row"><span class="row-copy"><strong>Marketplace updates</strong><p>Get demo updates about new listings.</p></span><button class="switch ${state.preferences.updates?'on':''}" role="switch" aria-checked="${state.preferences.updates}" aria-label="Marketplace updates" data-action="preference" data-key="updates"></button></div><div class="toggle-row"><span class="row-copy"><strong>Booking alerts</strong><p>Show notifications when you create a booking.</p></span><button class="switch ${state.preferences.bookingAlerts?'on':''}" role="switch" aria-checked="${state.preferences.bookingAlerts}" aria-label="Booking alerts" data-action="preference" data-key="bookingAlerts"></button></div><p class="group-label">Privacy & demo</p>${accountRow(['user','Profile','Update name, email and location','profile'])}${accountRow(['help','Help & safety','Frequently asked questions','help'])}<div class="notice-banner">${icon('shield')} No login, backend or actual payment processor is connected. Your changes remain on this device only.</div><button class="btn outline wide" data-action="resetdemo">${icon('refresh')} Reset all demo activity</button></div>`}
function notFound(){return `<div class="screen">${empty('search','We could not find that page','The item may have been removed, or the link may be incorrect.','Return home','home')}</div>`}
function renderSheet(){if(!ui.sheet)return '';let s=ui.sheet;let html='';let title='Options';if(s.type==='offer'){const l=getListing(s.id);title='Make an offer';html=l?`<div class="offer-context">${image(l)}<div><strong>${esc(l.title)}</strong><p>Listed at ${money(l.price)} / day</p></div></div><form data-form="offer" data-id="${l.id}"><label class="form-label" for="offer-amount">Your offer per day (K) *</label><input class="form-input" type="number" min="1" max="1000000" step="1" name="amount" id="offer-amount" inputmode="numeric" value="${Math.round(l.price*.85)}" required><label class="form-label" for="offer-note">Message to owner (optional)</label><textarea class="form-textarea" name="note" id="offer-note" placeholder="Explain your offer or preferred collection arrangements" maxlength="400"></textarea><div class="note">Interactive simulation: the example seller automatically accepts, counters, or declines. No real seller is contacted, and no money is collected.</div><button class="btn primary wide" type="submit">Submit demo offer ${icon('chevron')}</button></form>`:'<p>Listing unavailable.</p>'}
else if(s.type==='report'){title='Report an issue';html=`<p style="color:#666;margin-bottom:14px">Your report stays in this demo browser. Nothing is sent to a real moderation team.</p><form data-form="report"><input type="hidden" name="listingId" value="${esc(s.id||'')}"><label class="form-label" for="report-type">Reason</label><select id="report-type" class="form-select" name="reason"><option>Inaccurate listing details</option><option>Safety concern</option><option>Suspicious listing</option><option>Technical issue</option><option>Other feedback</option></select><label class="form-label" for="report-notes">Details</label><textarea class="form-textarea" name="details" id="report-notes" placeholder="Tell us what happened..." required></textarea><button class="btn primary wide" type="submit">Save demo report</button></form>`}
else if(s.type==='receipt'){const b=state.bookings.find(x=>String(x.id)===String(s.id));let l=b?getListing(b.listingId):null;title='Booking details';html=b?`<div class="price-summary"><div class="price-row"><span>Reference</span><strong>${esc(b.ref)}</strong></div><div class="price-row"><span>Item</span><strong>${esc(l?.title||'Item')}</strong></div><div class="price-row"><span>Start / end</span><strong>${b.start} – ${b.end}</strong></div><div class="price-row"><span>Status</span><strong>${esc(b.status)}</strong></div><div class="price-row"><span>Method</span><strong>${esc(b.method)}</strong></div><div class="price-row total"><span>Illustrative amount</span><strong>${money(b.total)}</strong></div></div><div class="note">Demo record only; this is not a receipt for a real payment.</div><button class="btn outline wide" data-action="copyref" data-id="${b.id}">${icon('link')} Copy reference</button>`:''}
return `<div class="sheet" role="presentation" data-action="closesheet"><div class="sheet-card" role="dialog" aria-modal="true" aria-label="${title}" ><div class="sheet-header"><h2>${title}</h2><button class="icon-btn" data-action="closesheet" aria-label="Close">${icon('close')}</button></div><div class="sheet-content">${html}</div></div></div>`}
function offersPage(){const items=state.offers.slice().reverse();return `<div class="screen reveal offers-screen"><div class="page-top"><h1>My offers</h1><p>Keep track of price proposals and simulated seller responses.</p></div><div class="notice-banner">${icon('info')} Offers and owner replies are demonstrations generated in this browser. No messages are delivered to real sellers.</div>${items.length?items.map(o=>{const l=getListing(o.listingId);return `<section class="offer-card"><div class="offer-context">${l?image(l):''}<div><strong>${esc(l?.title||'Listing removed')}</strong><p>${esc(l?.owner||'Example owner')} · ${esc(l?.city||'Zambia')}</p></div></div><div class="offer-facts"><div><span>Your offer</span><strong>${money(o.amount)} / day</strong></div><div><span>Example seller response</span><strong class="offer-status ${o.status==='Accepted'?'offer-accepted':o.status==='Counteroffer'?'offer-counter':'offer-declined'}">${esc(o.status)}</strong></div></div>${o.status==='Counteroffer'?`<div class="offer-response">The demo seller suggests <strong>${money(o.counter)} / day</strong>. Accept this rate to continue to booking.</div><div class="offer-buttons"><button class="btn primary" data-action="acceptcounter" data-id="${o.id}">Accept ${money(o.counter)}</button><button class="btn outline" data-action="declinecounter" data-id="${o.id}">Decline</button></div>`:o.status==='Accepted'?`<div class="offer-response">Agreed demo rate: <strong>${money(o.agreedRate)} per day</strong>.</div><div class="offer-buttons"><button class="btn primary" data-action="bookoffer" data-id="${o.id}">Book at agreed rate ${icon('chevron')}</button></div>`:`<p class="subtle" style="margin-top:13px">${o.status==='Declined'?'The demo seller did not accept this price. You can submit a different offer.':'This offer has been closed.'}</p>`}${l?`<button class="link-btn" data-action="listing" data-id="${l.id}">View listing</button> ${o.status==='Declined'?`<button class="link-btn" data-action="offer" data-id="${l.id}">Make another offer</button>`:''}`:''}</section>`}).join(''):empty('handshake','No offers yet','Open a listing and select Make an offer to propose a demo rental rate.','Explore listings','explore')}</div>`}
function routeView(page,id){switch(page){case'home':return home();case'explore':case'trending':return explore(page);case'listing':return detail(getListing(id));case'offers':return offersPage();case'book':return book(getListing(id));case'checkout':return checkout(getListing(id));case'success':return bookingSuccess(id);case'comments':return commentsPage(getListing(id));case'post':return postPage();case'edit':return postPage(id);case'account':return account();case'notifications':return notifications();case'messages':return conversations();case'chat':return chatPage(id);case'mylistings':return myListings();case'rentals':return rentals();case'saved':return savedPage();case'profile':return profilePage();case'paymentmethods':return paymentMethods();case'payouts':return payoutPage();case'help':return helpPage();case'settings':return settingsPage();default:return notFound()}}
function render(preserve=false){let y=preserve?scrollY:0;let carousel=preserve?$('.trending-rail')?.scrollLeft:0;const [page='home',id]=pagePath();$('#app').innerHTML=header(page)+`<main class="shell">${routeView(page,id)}</main>`+navBar(page)+renderSheet();if(preserve){scrollTo(0,y);const el=$('.trending-rail');if(el)el.scrollLeft=carousel}else{scrollTo(0,0);if(page==='chat'){const target=$('#messages-list');if(target)requestAnimationFrame(()=>target.lastElementChild?.scrollIntoView({block:'end',behavior:'instant'}))}}document.title=`${page==='home'?'ATM — Anything to Hire':page[0].toUpperCase()+page.slice(1)+' | ATM'}`}
function notify(title,text,route,kind='booking'){if(!state.preferences.bookingAlerts&&kind==='booking')return;state.notifications.unshift({id:Date.now()+Math.floor(Math.random()*99),title,text,route,kind,age:'Now',read:false})}
function toggleIn(list,id){const s=String(id),index=list.indexOf(s);if(index>=0)list.splice(index,1);else list.push(s)}
function ensureChat(listingId){let l=getListing(listingId);if(!l)return null;let c=state.conversations.find(c=>String(c.listingId)===String(l.id));if(!c){c={id:Date.now(),listingId:l.id,person:l.owner,messages:[{me:false,text:`Hello! This is a simulated chat about ${l.title}. Messages are not delivered to real sellers.`,time:'Now'}]};state.conversations.unshift(c);save()}return c}
function addSupport(){let c=state.conversations.find(c=>c.person==='ATM Demo Support');if(!c){c={id:Date.now(),listingId:0,person:'ATM Demo Support',messages:[{me:false,text:'Welcome to ATM demo support. Ask a question or report an issue. No live staff are connected.',time:'Now'}]};state.conversations.unshift(c);save()}go('chat',c.id)}
function shareListing(id){let l=getListing(id);if(!l)return;const url=location.href.split('#')[0]+'#/listing/'+encodeURIComponent(id);if(navigator.share){navigator.share({title:l.title,text:'Check out this ATM rental marketplace demo listing.',url}).then(()=>toast('Shared successfully')).catch(()=>{});}else if(navigator.clipboard?.writeText){navigator.clipboard.writeText(url).then(()=>toast('Listing link copied')).catch(()=>fallbackCopy(url))}else fallbackCopy(url)}
function fallbackCopy(text){let e=document.createElement('textarea');e.value=text;document.body.appendChild(e);e.select();try{document.execCommand('copy');toast('Link copied')}catch(_){toast('Unable to copy on this device')}e.remove()}
function selectCategory(c){ui.category=c;ui.query='';ui.city='All cities';ui.sort='Trending';go('explore')}
function selectSortOrCity(field,value){ui[field]=value;render(true)}
function act(a){const action=a.dataset.action, id=a.dataset.id,route=a.dataset.route;switch(action){
case'go':ui.sheet=null;go(route,id);break;
case'back':if(history.length>1)history.back();else go('home');break;
case'search':go('explore');requestAnimationFrame(()=>$('#search-listings')?.focus());break;
case'category':selectCategory(a.dataset.value);break;
case'resetfilters':ui.category='All';ui.city='All cities';ui.sort='Trending';ui.query='';if(pagePath()[0]==='trending')go('explore');else render(true);break;
case'listing':go('listing',id);break;
case'book':ui.booking=null;go('book',id);break;
 case'offer':ui.sheet={type:'offer',id};render(true);break;
 case'acceptcounter':{const o=state.offers.find(x=>String(x.id)===String(id));if(o?.status==='Counteroffer'){o.status='Accepted';o.agreedRate=o.counter;notify('Offer accepted',`Agreed demo rate: ${money(o.agreedRate)} / day`,'offers','tip');save();render(true);toast('Counteroffer accepted (demo)')}break}
 case'declinecounter':{const o=state.offers.find(x=>String(x.id)===String(id));if(o?.status==='Counteroffer'){o.status='Declined';save();render(true);toast('Counteroffer declined')}break}
 case'bookoffer':{const o=state.offers.find(x=>String(x.id)===String(id));if(o?.status==='Accepted'&&getListing(o.listingId)){ui.booking={id:o.listingId,agreedRate:o.agreedRate,offerId:o.id};go('book',o.listingId)}break}
case'gallery':ui.photoIdx=Number(a.dataset.index);render(true);break;
case'save':toggleIn(state.favorites,id);save();render(true);toast(saved(id)?'Saved to your favourites':'Removed from saved items');break;
case'like':toggleIn(state.likes,id);save();render(true);break;
case'comments':go('comments',id);break;
case'share':shareListing(id);break;
case'chat':{let c=ensureChat(id);if(c)go('chat',c.id);break}
case'closesheet':ui.sheet=null;render(true);break;
case'report':ui.sheet={type:'report',id:null};render(true);break;
case'notification':{let n=state.notifications.find(n=>String(n.id)===String(id));if(!n)break;n.read=true;save();go(n.route||'notifications');break}
case'markall':state.notifications.forEach(n=>n.read=true);save();render(true);toast('All notifications marked as read');break;
case'editlisting':go('edit',id);break;
case'deletelisting':if(confirm('Delete this demo listing? You can no longer open it after deletion.')){let l=myListing(id);if(l)l.deleted=true;save();render(true);toast('Demo listing deleted')}break;
case'cancelbooking':if(confirm('Cancel this demo booking request?')){let b=state.bookings.find(x=>String(x.id)===String(id));if(b){b.status='Cancelled';notify('Booking cancelled','Your demo rental request was cancelled.','rentals','booking')}save();render(true);toast('Booking cancelled')}break;
case'receipt':ui.sheet={type:'receipt',id};render(true);break;
case'copyref':{let b=state.bookings.find(x=>String(x.id)===String(id));if(b)fallbackCopy(b.ref);break}
case'faq':ui.helpOpen=ui.helpOpen===Number(id)?-1:Number(id);render(true);break;
case'support':addSupport();break;
case'preference':state.preferences[a.dataset.key]=!state.preferences[a.dataset.key];save();render(true);toast('Preference saved');break;
case'removemethod':state.paymentMethods.splice(Number(id),1);save();render(true);toast('Demo method removed');break;
case'resetdemo':if(confirm('Reset ATM demo? This will erase your sample account changes, bookings, saved items, chats and listings from this browser.')){state=defaultState();ui.category='All';ui.city='All cities';ui.query='';save();go('home');toast('ATM demo reset')}break;
}}
function formSubmit(form){const type=form.dataset.form,data=new FormData(form),id=form.dataset.id;switch(type){
case'quickbook':case'book':{let l=getListing(id),start=String(data.get('start')||''),end=String(data.get('end')||'');const valid=l&&/^\d{4}-\d\d-\d\d$/.test(start)&&/^\d{4}-\d\d-\d\d$/.test(end)&&start>=dateISO(new Date())&&end>=start&&daysBetween(start,end)<=90;if(!valid){toast('Choose valid dates within a 90-day period');return}ui.booking={id:l.id,start,end,fulfillment:String(data.get('fulfillment')||'Pick up from host'),note:String(data.get('note')||''),agreedRate:ui.booking?.agreedRate,offerId:ui.booking?.offerId};if(type==='quickbook')go('book',id);else go('checkout',id);break}
case'offer':{const l=getListing(id),amount=Math.round(Number(data.get('amount'))),note=String(data.get('note')||'').trim();if(!l||!Number.isFinite(amount)||amount<1||amount>1000000){toast('Enter a valid offer amount');return}const status=amount>=l.price*.9?'Accepted':amount>=l.price*.65?'Counteroffer':'Declined';const counter=status==='Counteroffer'?Math.min(l.price,Math.ceil((amount+l.price)/20)*10):null;const o={id:Date.now()+Math.floor(Math.random()*10000),listingId:l.id,amount,note,status,counter,agreedRate:status==='Accepted'?amount:null,created:Date.now()};state.offers.push(o);notify('Demo offer response',`${l.title}: ${status}${counter?' at '+money(counter)+'/day':''}`,'offers','tip');save();ui.sheet=null;go('offers');toast('Demo offer submitted');break}
case'checkout':{let l=getListing(id),b=ui.booking;if(!l||!b||String(b.id)!==String(id)){toast('Please choose your hire dates');go('book',id);return}let days=daysBetween(b.start,b.end);let item={id:Date.now(),ref:'ATM-'+Math.random().toString(36).slice(2,8).toUpperCase(),listingId:l.id,start:b.start,end:b.end,fulfillment:b.fulfillment,note:b.note,days,method:String(data.get('method')||'Pay on handover (demo)'),status:'Confirmed (demo)',agreedRate:b.agreedRate,offerId:b.offerId,total:(b.agreedRate??l.price)*days+l.deposit,created:Date.now()};state.bookings.push(item);notify('Demo booking created',`${l.title} · ${b.start} to ${b.end}`,'rentals');save();ui.booking=null;go('success',item.id);break}
case'post':{const title=String(data.get('title')||'').trim(),category=String(data.get('category')),city=String(data.get('city')),price=Number(data.get('price')),description=String(data.get('description')||'').trim(),deposit=Number(data.get('deposit'))||0;if(title.length<5||description.length<20||!Number.isFinite(price)||price<=0){toast('Complete the required listing fields');return}let existing=id?myListing(id):null;let matching=ATM_LISTINGS.find(l=>l.category===category);let imageUrl=ui.postPreview||String(data.get('image')||'').trim()||existing?.image||matching?.image||photo('tent');let fields={title,category,city,price,deposit,description,image:imageUrl,owner:state.name,img:matching?.img||'tent',rating:5,reviews:0,likes:0,comments:0,featured:false,verified:false,created:1,unit:'day'};if(existing){Object.assign(existing,fields)}else{existing={id:Date.now(),...fields};state.myListings.unshift(existing)}ui.postPreview='';notify(existing?'Demo listing published':'Demo listing published',`${title} is now visible in Explore.`,'mylistings','post');save();go('listing',existing.id);toast(id?'Changes saved':'Demo listing published');break}
case'chat':{const c=state.conversations.find(c=>String(c.id)===String(id));const message=String(data.get('message')||'').trim();if(!c||!message)return;c.messages.push({me:true,text:message,time:'Now'});c.messages.push({me:false,text:'This is a demo conversation. Your message was saved locally; no real host receives it.',time:'Now'});save();render(true);const list=$('#messages-list');if(list)requestAnimationFrame(()=>list.lastElementChild?.scrollIntoView({block:'end',behavior:'smooth'}));toast('Demo message sent');break}
case'comment':{const message=String(data.get('comment')||'').trim();if(!message)return;(state.comments[id]??=[]).push({name:state.name,text:message});save();render(true);toast('Comment added');break}
case'profile':{state.name=String(data.get('name')||'').trim();state.email=String(data.get('email')||'').trim();state.city=String(data.get('city')||'Lusaka');save();go('account');toast('Profile updated');break}
case'method':{let number=String(data.get('number')||'').replace(/\D/g,'');if(number.length<9||number.length>13){toast('Enter a valid example mobile number');return}state.paymentMethods.push({provider:String(data.get('provider')),masked:'••••••'+number.slice(-3)});save();render(true);toast('Demo payment preference saved');break}
case'payout':state.payout={provider:String(data.get('provider')),label:String(data.get('label')||'').trim()};save();toast('Demo payout preference saved');render(true);break;
case'report':state.reports.push({listingId:String(data.get('listingId')||''),reason:String(data.get('reason')),details:String(data.get('details')).trim()});ui.sheet=null;save();render(true);toast('Report saved in this browser (demo only)');break;
}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='closesheet'&&b.classList.contains('sheet')&&e.target.closest('.sheet-card'))return;if(b.tagName==='BUTTON'||b.closest('button'))e.preventDefault();act(b)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.feed-card[data-action]')){e.preventDefault();act(e.target)}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;formSubmit(form)});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.change==='city')selectSortOrCity('city',t.value);else if(t.dataset.change==='sort')selectSortOrCity('sort',t.value);else if(t.dataset.upload){const file=t.files?.[0];if(!file)return;if(file.size>1.5*1024*1024){toast('Choose an image smaller than 1.5 MB');t.value='';return}if(!file.type.startsWith('image/')){toast('Choose an image file');return}let rd=new FileReader();rd.onload=()=>{ui.postPreview=String(rd.result);const box=$('#post-photo');if(box)box.innerHTML=`<img src="${ui.postPreview}" alt="Uploaded photo preview">`;toast('Photo added')};rd.readAsDataURL(file)}else if(t.id==='post-image'&&t.value){ui.postPreview=t.value;const box=$('#post-photo');if(box)box.innerHTML=`<img src="${esc(t.value)}" alt="Photo preview" onerror="this.style.display='none'">`}else if(t.type==='radio'&&t.name==='method'){document.querySelectorAll('.payment-option').forEach(x=>x.classList.toggle('selected',x.contains(t)))}});
let searchTimer;
document.addEventListener('input',e=>{if(e.target.dataset.input==='search'){ui.query=e.target.value;clearTimeout(searchTimer);const input=e.target;const pos=input.selectionStart;searchTimer=setTimeout(()=>{render(true);const f=$('#search-listings');if(f){f.focus();f.setSelectionRange(pos,pos)}},210)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.sheet){ui.sheet=null;render(true)}});
window.addEventListener('hashchange',()=>render());
if(!location.hash)history.replaceState(null,'','#/home');render();
})();
